// Offline support: every file of this build (the app and the emulator) is cached on install, so the installed app
// starts without a network. Other sites (the community catalog, firmware downloads) always go to the network.
// Generated by vite.config.ts from sw.template.js; VERSION changes whenever any file does.
const VERSION = "__VERSION__";
const FILES = __FILES__;
const CACHE = "fm1-swapper-" + VERSION;

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES.map((f) => new Request(f, { cache: "reload" })))));
});

self.addEventListener("activate", (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith("fm1-swapper-") && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

// the page asks the new version to take over when the user chooses "Reload"
self.addEventListener("message", (e) => { if (e.data === "skipWaiting") self.skipWaiting(); });

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // the emulator asks for its files with ?v=<build> stamps
    // the app's own page answers for its folder only (the emulator page in emu/ is cached under its own address)
    const root = new URL("./", self.location).pathname, path = new URL(req.url).pathname;
    const hit = await cache.match(req, { ignoreSearch: true })
      ?? (req.mode === "navigate" && (path === root || path === root + "index.html") ? await cache.match("./index.html") : undefined);
    if (!hit) return fetch(req);
    // hosts that redirect x/index.html to x/ (Cloudflare Pages): a cached redirect can't answer a page load
    return hit.redirected ? new Response(hit.body, { status: hit.status, statusText: hit.statusText, headers: hit.headers }) : hit;
  })());
});
